CREATE DATABASE IF NOT EXISTS propverse_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE propverse_db;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'ADMIN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE projects(project_id INT AUTO_INCREMENT PRIMARY KEY,project_name VARCHAR(150) NOT NULL,location VARCHAR(180) NOT NULL,client_name VARCHAR(150),start_date DATE,end_date DATE,budget DECIMAL(14,2) DEFAULT 0,status ENUM('PLANNED','ONGOING','COMPLETED','ON_HOLD') NOT NULL DEFAULT 'PLANNED',progress_percentage INT NOT NULL DEFAULT 0,CHECK(budget>=0),CHECK(progress_percentage BETWEEN 0 AND 100)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE workers(worker_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,role VARCHAR(80) NOT NULL,phone VARCHAR(30),email VARCHAR(150),project_id INT NULL,availability_status ENUM('AVAILABLE','BUSY','UNAVAILABLE') NOT NULL DEFAULT 'AVAILABLE',FOREIGN KEY(project_id) REFERENCES projects(project_id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tasks(task_id INT AUTO_INCREMENT PRIMARY KEY,task_name VARCHAR(150) NOT NULL,project_id INT NOT NULL,assigned_worker_id INT NULL,start_date DATE,deadline DATE,status ENUM('PENDING','IN_PROGRESS','COMPLETED') NOT NULL DEFAULT 'PENDING',progress_percentage INT NOT NULL DEFAULT 0,description TEXT,FOREIGN KEY(project_id) REFERENCES projects(project_id) ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY(assigned_worker_id) REFERENCES workers(worker_id) ON DELETE RESTRICT ON UPDATE CASCADE,CHECK(progress_percentage BETWEEN 0 AND 100)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE issues(issue_id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,issue_title VARCHAR(180) NOT NULL,description TEXT,priority ENUM('LOW','MEDIUM','HIGH') NOT NULL DEFAULT 'MEDIUM',status ENUM('OPEN','IN_PROGRESS','RESOLVED') NOT NULL DEFAULT 'OPEN',reported_date DATE NOT NULL DEFAULT (CURRENT_DATE),resolution_notes TEXT,FOREIGN KEY(project_id) REFERENCES projects(project_id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
